from typing import List

def canFinish(n: int, prerequisites: List[List[int]]) -> bool:
    graph = {i: [] for i in range(n)}
    visited = [0] * n

    for pair in prerequisites:
        graph[pair[1]].append(pair[0])

    def dfs(i):
        if visited[i] == -1:
            return False
        if visited[i] == 1:
            return True
        visited[i] = -1
        for j in graph[i]:
            if not dfs(j):
                return False
        visited[i] = 1
        return True

    for i in range(n):
        if not dfs(i):
            return False
    return True
